def decimal_to_base4(n):
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        remainder = n % 4
        digits.append(remainder)
        n = n // 4
    digits.reverse()
    result = []
    for d in digits:
        if d < 10:
            result.append(str(d))
        else:
            result.append(chr(ord('a') + d - 10))
    return ''.join(result)

